 * Create a global object that is used as the shared global for all ext-*.js
 * scripts that are loaded via `loadScript`.
 *
 * @returns {object} A sandbox that is used as the global by `loadScript`.
 */
_createExtGlobal() {
  let global = Cu.Sandbox(
    Services.scriptSecurityManager.getSystemPrincipal(),
    {
      wantXrays: false,
      wantGlobalProperties: ["ChromeUtils"],
      sandboxName: `Namespace of ext-*.js scripts for ${this.processType} (from: resource://gre/modules/ExtensionCommon.sys.mjs)`,
    }
  );

  Object.assign(global, {
    global, // This must be first, see bug 1977694.
    AppConstants,
    Cc,
    ChromeWorker,
    Ci,
    Cr,
    Cu,
    ExtensionAPI,
    ExtensionAPIPersistent,
    ExtensionCommon,
    FileReader,
    Glean,
    GleanPings,
    IOUtils,
    L10nFileSource,
    L10nRegistry,
    MatchGlob,
    MatchPattern,
    MatchPatternSet,
    OffscreenCanvas,
    PathUtils,
    Services,
    StructuredCloneHolder,
    WebExtensionPolicy,
    XPCOMUtils,
    extensions: this,
  });

  ChromeUtils.defineLazyGetter(global, "console", getConsole);
  // eslint-disable-next-line mozilla/lazy-getter-object-name
  ChromeUtils.defineESModuleGetters(global, {
    ExtensionUtils: "resource://gre/modules/ExtensionUtils.sys.mjs",
  });

  return global;
}

var { ExtensionSupport } = ChromeUtils.importESModule(
  "resource:///modules/ExtensionSupport.sys.mjs"
);
var { AccountManager, FolderManager } = ChromeUtils.importESModule(
  "resource:///modules/ExtensionAccounts.sys.mjs"
);
var { MessageListTracker, MessageTracker, MessageManager, TagTracker } =
  ChromeUtils.importESModule("resource:///modules/ExtensionMessages.sys.mjs");
var { SpaceTracker } = ChromeUtils.importESModule(
  "resource:///modules/ExtensionSpaces.sys.mjs"
);
var { ProtectedToolbarButtonTracker } = ChromeUtils.importESModule(
  "resource:///modules/ExtensionToolbarButtons.sys.mjs"
);
var { XPCOMUtils } = ChromeUtils.importESModule(
  "resource://gre/modules/XPCOMUtils.sys.mjs"
);
